patches.replacement:
let os_info = os_info::get();
let originator = originator();
// ccodex: UA 的 OS/终端段支持环境变量覆盖（跨平台编译/运行时保持固定指纹，默认 Windows）
let os_type = std::env::var("CCODEX_UA_OS_TYPE").unwrap_or_else(|_| os_info.os_type().to_string());
let os_version = std::env::var("CCODEX_UA_OS_VERSION").unwrap_or_else(|_| os_info.version().to_string());
let os_arch = std::env::var("CCODEX_UA_ARCH").ok().or_else(|| os_info.architecture().map(str::to_string)).unwrap_or_else(|| "unknown".to_string());
let terminal = std::env::var("CCODEX_UA_TERMINAL").unwrap_or_else(|_| user_agent());
let prefix = format!("{}/{build_version} ({os_type} {os_version}; {os_arch}) {terminal}", originator.value.as_str());

